    ":" : ":",
    "A decision needs a short reason. Add one and try again." : "Eine Entscheidung braucht eine kurze Begründung. Füge eine hinzu und versuche es erneut.",
    "A full archive bundle will be produced and the team will be permanently deleted immediately after." : "Ein vollständiges Archivpaket wird erzeugt und das Team wird unmittelbar danach endgültig gelöscht.",
    "A full archive bundle will be produced, then the team will be soft-deleted with a 30-day grace period during which administrators can restore it." : "Ein vollständiges Archivpaket wird erzeugt, danach wird das Team soft-gelöscht mit einer Karenzfrist von 30 Tagen, in der Administratoren es wiederherstellen können.",
    "A full archive bundle will be produced, then the team will be soft-deleted with a 60-day grace period during which administrators can restore it." : "Ein vollständiges Archivpaket wird erzeugt, danach wird das Team soft-gelöscht mit einer Karenzfrist von 60 Tagen, in der Administratoren es wiederherstellen können.",
    "A team folder is now connected to this team" : "Ein Team-Ordner ist jetzt mit diesem Team verbunden",
    "A kickoff meeting to align the team on scope, timeline, and roles. Mark as done once it's on the calendar." : "Ein Kickoff-Meeting, um das Team hinsichtlich Umfang, Zeitplan und Rollen abzustimmen. Als erledigt markieren, sobald es im Kalender steht.",
    "A message with a link to the meeting notes will be posted in the Talk room asking team members to add agenda items." : "Im Talk-Raum wird eine Nachricht mit einem Link zu den Besprechungsnotizen gepostet, in der Teammitglieder gebeten werden, Tagesordnungspunkte hinzuzufügen.",
    "A new message from TeamHub" : ["Eine neue Nachricht von TeamHub","{n} neue Nachrichten von TeamHub"],
    "A new message from TeamHub is waiting for you." : ["Eine neue Nachricht von TeamHub wartet auf Sie.","{n} neue Nachrichten von TeamHub warten auf Sie."],
    "A notes file is created in the team Meetings folder and linked from the calendar event." : "Eine Notizdatei wird im Ordner Meetings des Teams erstellt und mit dem Kalendereintrag verknüpft.",
    "A project-flavoured team with the familiar setup — no lifecycle tools." : "Ein Team im Projekt-Stil mit der gewohnten Einrichtung — ohne Lebenszyklus-Werkzeuge.",
    "A retro to look back on scope, timeline, budget, and what to carry into the next project. Optional — mark as done once it's on the calendar, or skip if you don't want to run one." : "Eine Retrospektive, um auf Umfang, Zeitplan, Budget und Erkenntnisse für das nächste Projekt zurückzublicken. Optional — als erledigt markieren, sobald es im Kalender steht, oder überspringen, wenn Sie keine durchführen möchten.",
    "A short description for accessibility" : "Eine kurze Beschreibung für die Barrierefreiheit",
    "A single project-level role. A member sees the Time tab when their team role is at or above this level." : "Eine einzige Rolle auf Projektebene. Ein Mitglied sieht den Zeit-Tab, wenn seine Teamrolle mindestens diese Stufe hat.",
    "A source that is turned off, or whose app is missing, is skipped entirely. A source that fails at request time never blocks the others — members see the results that did arrive plus a notice." : "Eine ausgeschaltete Quelle oder eine, deren App fehlt, wird vollständig übersprungen. Eine Quelle, die bei einer Anfrage fehlschlägt, blockiert die anderen nie — Mitglieder sehen die eingegangenen Ergebnisse und einen Hinweis.",
    "A team admin can add categories under Manage team → Decisions." : "Ein Teamadministrator kann Kategorien unter Team verwalten → Entscheidungen hinzufügen.",
    "A token is currently configured. Leave the field empty to keep it, paste a new value to replace it, or type __CLEAR__ to remove it." : "Ein Token ist derzeit konfiguriert. Lassen Sie das Feld leer, um es zu behalten, fügen Sie einen neuen Wert ein, um es zu ersetzen, oder geben Sie __CLEAR__ ein, um es zu entfernen.",
