    "Add lane" : "Spur hinzufügen",
    "Add lanes to the Deck board as they become known. Each lane is a workstream that milestones and budget lanes hang off." : "Fügen Sie Spuren zum Deck-Board hinzu, sobald sie bekannt sind. Jede Spur ist ein Arbeitsstrom, an dem Meilensteine und Budget-Spuren hängen.",
    "Add lanes to the Deck board as they become known. Each lane is a workstream — a milestone owns cards from the lanes above it, and Budget can allocate a share to each. New Advanced projects start with only the Project management lane; add the rest here as your plan takes shape." : "Fügen Sie Spuren zum Deck-Board hinzu, sobald sie bekannt sind. Jede Spur ist ein Arbeitsstrom — ein Meilenstein besitzt die Karten aus den darüber liegenden Spuren, und das Budget kann jeder Spur einen Anteil zuweisen. Neue Erweiterte Projekte starten nur mit der Spur „Projektmanagement“; fügen Sie den Rest hier hinzu, während sich Ihr Plan entwickelt.",
    "Add members" : "Mitglieder hinzufügen",
