    "Advanced projects require a valid TeamHub Business license. Ask your administrator to enter one from Settings → Administration → TeamHub → License." : "Erweiterte Projekte erfordern eine gültige TeamHub-Business-Lizenz. Bitten Sie Ihren Administrator, eine unter Einstellungen → Verwaltung → TeamHub → Lizenz einzugeben.",
