    "An archive of the collective will be produced and the collective will be permanently deleted immediately after." : "Es wird ein Archiv des Kollektivs erstellt und das Kollektiv unmittelbar danach endgültig gelöscht.",
    "An archive of the collective will be produced, then it will be moved to Collectives' trash for a 30-day grace period before being permanently deleted." : "Es wird ein Archiv des Kollektivs erstellt; anschließend wird es für eine Schonfrist von 30 Tagen in den Papierkorb von Collectives verschoben, bevor es endgültig gelöscht wird.",
    "An archive of the collective will be produced, then it will be moved to Collectives' trash for a 60-day grace period before being permanently deleted." : "Es wird ein Archiv des Kollektivs erstellt; anschließend wird es für eine Schonfrist von 60 Tagen in den Papierkorb von Collectives verschoben, bevor es endgültig gelöscht wird.",
