    "Anchors the timeline so milestones and the project-health widget have a range to report against. Both fields are optional but recommended." : "Verankert die Zeitleiste, sodass Meilensteine und das Projektzustands-Widget einen Berichtsbereich haben. Beide Felder sind optional, aber empfohlen.",
    "Anonymous usage statistics are sent daily. This instance has no active license, so telemetry is enabled." : "Anonyme Nutzungsstatistiken werden täglich gesendet. Diese Instanz hat keine aktive Lizenz, daher ist die Telemetrie aktiviert.",
