    "Answer the nine questions below to define this project. Each answer becomes part of the project's shared understanding — update them as the project evolves." : "Beantworten Sie die neun untenstehenden Fragen, um dieses Projekt zu definieren. Jede Antwort wird Teil des gemeinsamen Projektverständnisses — aktualisieren Sie sie im Projektverlauf.",
