    "Heads up: any app resource connected to this team (calendar, folder, board, conversation) will be permanently deleted along with the team — even if it was created outside TeamHub. To preserve a connected resource, remove this team from its sharing permissions before deleting the team." : "Hinweis: Alle mit diesem Team verknüpften App-Ressourcen (Kalender, Ordner, Board, Gespräch) werden zusammen mit dem Team endgültig gelöscht — selbst wenn sie außerhalb von TeamHub erstellt wurden. Um eine verknüpfte Ressource zu erhalten, entferne dieses Team zuerst aus den Freigabeberechtigungen, bevor du das Team löschst.",
