    "If this colleague was just added via single sign-on (Microsoft Entra, SAML, or OIDC), they need to sign in to Nextcloud once before they can be added to a team." : "Wenn dieser Kollege gerade über Single Sign-on (Microsoft Entra, SAML oder OIDC) hinzugefügt wurde, muss er sich einmal bei Nextcloud anmelden, bevor er einem Team hinzugefügt werden kann.",
    "If you want a recoverable copy, ask your Nextcloud administrator to enable archiving before continuing." : "Wenn Sie eine wiederherstellbare Kopie wünschen, bitten Sie Ihre Nextcloud-Administration, die Archivierung zu aktivieren, bevor Sie fortfahren.",
