    "Images inserted from personal files are copied to a hidden cache folder in the team folder so all members can view them. Clearing shows broken images in existing posts." : "Aus persönlichen Dateien eingefügte Bilder werden in einen versteckten Cache-Ordner im Team-Ordner kopiert, damit alle Mitglieder sie sehen können. Nach dem Leeren erscheinen defekte Bilder in bestehenden Beiträgen.",
    "Images inserted from your personal files are copied into a hidden cache folder (.teamhub-cache) inside the team folder so all members can view them. Clear this cache to free up storage — existing messages will show broken images." : "Bilder, die aus Ihren persönlichen Dateien eingefügt werden, werden in einen versteckten Cache-Ordner (.teamhub-cache) im Teamordner kopiert, damit alle Mitglieder sie anzeigen können. Leeren Sie diesen Cache, um Speicher freizugeben — bestehende Nachrichten werden dann fehlerhafte Bilder anzeigen.",
