    "Milestones" : "Meilensteine",
    "Milestones appear as a red marker line on the Timeline tab, with the label you give them. Useful for tracking key dates such as launches or deadlines at a glance." : "Meilensteine erscheinen als rote Markierungslinie auf der Registerkarte Zeitleiste, mit der von Ihnen vergebenen Bezeichnung. Praktisch, um wichtige Termine wie Markteinführungen oder Fristen auf einen Blick zu verfolgen.",
    "Milestones mark key project dates such as launches or deadlines. Every Deck card whose due date falls between a milestone and the previous one belongs to that milestone — the project-health widget uses this to flag work at risk of slipping. When Timeline is enabled, they also appear as red marker lines there." : "Meilensteine markieren wichtige Projekttermine wie Veröffentlichungen oder Fristen. Jede Deck-Karte, deren Fälligkeitsdatum zwischen einem Meilenstein und dem vorherigen liegt, gehört zu diesem Meilenstein — das Projektzustands-Widget nutzt dies, um gefährdete Arbeit zu kennzeichnen. Wenn die Zeitleiste aktiviert ist, erscheinen sie dort auch als rote Markierungslinien.",
    "Milestones own the Deck cards due before them and feed the project-health widget." : "Meilensteine besitzen die vor ihnen fälligen Deck-Karten und speisen das Projektzustands-Widget.",
