    "Set the project total, then allocate a share to each workstream (Deck stack). Per-workstream view and edit permissions decide who sees the lane and who can add or change expenses." : "Lege zuerst den Projektbetrag fest, dann verteile einen Anteil auf jeden Arbeitsstrang (Deck-Stapel). Pro Arbeitsstrang legen die Anzeige- und Bearbeitungsrechte fest, wer die Spur sieht und wer Ausgaben hinzufügen oder ändern kann.",
