    "Set your typical weekly presence below. Changes take effect after you click Save. Use the calendar to override individual dates." : "Legen Sie unten Ihre typische wöchentliche Anwesenheit fest. Änderungen werden wirksam, nachdem Sie auf Speichern geklickt haben. Verwenden Sie den Kalender, um einzelne Daten zu überschreiben.",
