    "Team type" : "Teamtyp",
    "Team visibility restored. Run occ circles:maintenance to rebuild caches." : "Teamsichtbarkeit wiederhergestellt. Führen Sie occ circles:maintenance aus, um die Caches neu aufzubauen.",
    "Team wiki and pages (Intravox)" : "Team-Wiki und Seiten (Intravox)",
    "Team-creator group configured above" : "Team-Ersteller-Gruppe oben konfiguriert",
    "TeamHub" : "TeamHub",
    "TeamHub can send anonymous usage data to help improve the app. No URLs, hostnames, or user data are ever included — only an anonymous UUID and aggregate counts." : "TeamHub kann anonyme Nutzungsdaten senden, um die App zu verbessern. Es werden niemals URLs, Hostnamen oder Benutzerdaten einbezogen — nur eine anonyme UUID und aggregierte Zählungen.",
    "TeamHub runs without a license. Advanced projects and the What’s new feed stay unavailable until one is installed, on the License tab." : "TeamHub läuft ohne Lizenz. Erweiterte Projekte und der Was-gibt-es-Neues-Feed bleiben nicht verfügbar, bis auf dem Reiter Lizenz eine Lizenz installiert wird.",
    "TeamHub will copy all files from the shared folder into the team folder. If the team folder already has files, they will first be moved to a backup folder called \"team_files_backup\". The shared folder will remain intact but the team will no longer have access to it." : "TeamHub kopiert alle Dateien aus dem geteilten Ordner in den Team-Ordner. Wenn der Team-Ordner bereits Dateien enthält, werden diese zunächst in einen Sicherungsordner namens \"team_files_backup\" verschoben. Der geteilte Ordner bleibt intakt, aber das Team hat keinen Zugriff mehr darauf.",
    "TeamHub will create a dedicated space in each checked app and add the team as a member." : "TeamHub erstellt in jeder ausgewählten App einen dedizierten Bereich und fügt das Team als Mitglied hinzu.",
    "TeamHub will create a dedicated space in each selected app and add this team as a member." : "TeamHub erstellt in jeder ausgewählten App einen dedizierten Bereich und fügt dieses Team als Mitglied hinzu.",
    "Teams" : "Teams",
    "Teams are shared spaces for messages, files, calendars and tasks. Create your first team, or browse the ones you can join." : "Teams sind gemeinsame Bereiche für Nachrichten, Dateien, Kalender und Aufgaben. Erstellen Sie Ihr erstes Team oder durchsuchen Sie die Teams, denen Sie beitreten können.",
    "Teams navigation" : "Teams-Navigation",
    "Teams pending deletion or with a failed archive attempt" : "Teams mit ausstehender Löschung oder fehlgeschlagenem Archivierungsversuch",
    "Teams this user belongs to" : "Teams, in denen dieser Benutzer Mitglied ist",
    "Teams with corrupted config" : "Teams mit beschädigter Konfiguration",
    "Teams with no live owner. Assign a new owner under Maintenance → All teams to restore governance." : "Teams ohne aktiven Eigentümer. Weisen Sie unter Wartung → Alle Teams einen neuen Eigentümer zu, um die Verwaltung wiederherzustellen.",
    "Telemetry" : "Telemetrie",
    "Telemetry contents" : "Telemetrie-Inhalte",
    "Telemetry details" : "Details zur Telemetrie",
    "Telemetry is OFF" : "Telemetrie ist AUS",
