    "Time settings" : "Zeiteinstellungen",
    "Time settings saved" : "Zeiteinstellungen gespeichert",
    "Time to wrap up. Tie off loose ends, evaluate the project with your team, and archive it once everything is settled." : "Zeit zum Abschluss. Erledigen Sie offene Punkte, evaluieren Sie das Projekt mit Ihrem Team und archivieren Sie es, sobald alles geklärt ist.",
    "Time to wrap up. Tie off loose ends, evaluate the project with your team, and archive it once everything is settled. Dedicated closing tools are coming in a future update." : "Zeit zum Abschließen. Erledigen Sie letzte Punkte, werten Sie das Projekt mit Ihrem Team aus und archivieren Sie es, sobald alles geregelt ist. Eigene Abschluss-Werkzeuge folgen in einem zukünftigen Update.",
    "Time utilisation" : "Zeitauslastung",
    "Time utilisation. {v}% logged." : "Zeitauslastung. {v}% erfasst.",
    "Time windows" : "Zeitfenster",
