    "Time-bound work with clear goals" : "Zeitgebundene Arbeit mit klaren Zielen",
    "Timeline" : "Zeitleiste",
    "Timeline is disabled for this team — milestones you add here still drive the project-health widget, but will not appear on the Timeline tab until Timeline is enabled under Integration Settings." : "Die Zeitleiste ist für dieses Team deaktiviert — hier hinzugefügte Meilensteine steuern weiterhin das Projektzustands-Widget, erscheinen aber erst im Reiter Zeitleiste, wenn die Zeitleiste unter Integrationseinstellungen aktiviert wird.",
    "Timeline is disabled for this team. Enable it under the Integrations tab to manage milestones." : "Die Zeitleiste ist für dieses Team deaktiviert. Aktivieren Sie sie unter der Registerkarte Integrationen, um Meilensteine zu verwalten.",
