    "Verifies that the installed TeamHub code matches the released build. A SHA-256 manifest generated at build time is compared against the files on disk. Use this to detect unauthorised changes or a corrupted install." : "Prüft, ob der installierte TeamHub-Code dem veröffentlichten Build entspricht. Ein zur Build-Zeit erzeugtes SHA-256-Manifest wird mit den Dateien auf der Festplatte verglichen. So lassen sich unbefugte Änderungen oder eine beschädigte Installation erkennen.",
