    "Weekly template" : "Wochenvorlage",
    "Weekly template saved" : "Wochenvorlage gespeichert",
    "Welcome to TeamHub" : "Willkommen bei TeamHub",
    "We’ll suggest the best half-days within three working days of this date." : "Wir schlagen die besten Halbtage innerhalb von drei Werktagen um dieses Datum vor.",
    "What consequences might this project have — intended (tied to the objective), unintended-negative (risks), and unintended-positive (unplanned benefits)?" : "Welche Auswirkungen kann dieses Projekt haben — beabsichtigt (an das Ziel gekoppelt), unbeabsichtigt-negativ (Risiken) und unbeabsichtigt-positiv (ungeplante Vorteile)?",
    "What does this project explicitly not deliver? Framed negatively, to manage expectations." : "Was liefert dieses Projekt ausdrücklich nicht? Negativ formuliert, um Erwartungen zu steuern.",
    "What is the core issue this project addresses? Is this an opportunity to seize or a problem to solve? Would something genuinely go wrong if we did not act?" : "Was ist die zentrale Fragestellung, die dieses Projekt beantwortet? Ist dies eine Chance, die genutzt werden soll, oder ein Problem, das gelöst werden muss? Würde ohne Handeln wirklich etwas schiefgehen?",
    "What is this for?" : "Wofür ist das?",
    "What is this team about?" : "Worum geht es bei diesem Team?",
    "What kind of meeting is this?" : "Welche Art von Besprechung ist das?",
    "What needs to be decided?" : "Was muss entschieden werden?",
    "What needs your attention across all your teams" : "Was in all deinen Teams deine Aufmerksamkeit braucht",
    "What non-negotiable requirements has the sponsor set — quality, budget, or schedule?" : "Welche nicht verhandelbaren Anforderungen hat der Auftraggeber festgelegt — Qualität, Budget oder Zeitplan?",
    "What underlying ambition does this project serve? Multiple objectives are fine, as long as they do not contradict each other." : "Welchem übergeordneten Ziel dient dieses Projekt? Mehrere Ziele sind möglich, solange sie sich nicht widersprechen.",
    "What will the project team concretely deliver? It must be tangible and visible — something you can hand over when the project is done." : "Was liefert das Projektteam konkret? Es muss greifbar und sichtbar sein — etwas, das bei Abschluss übergeben werden kann.",
    "What would you like to ask?" : "Was möchten Sie fragen?",
    "What’s new" : "Was ist neu",
    "What’s new requires an active TeamHub license." : "„Was ist neu“ erfordert eine aktive TeamHub-Lizenz.",
    "What’s new requires an active TeamHub license. Add or renew a license in Admin settings → License to unlock the feed." : "„Was ist neu“ erfordert eine aktive TeamHub-Lizenz. Füge eine Lizenz hinzu oder erneuere sie in den Admin-Einstellungen → Lizenz, um den Feed freizuschalten.",
    "What’s next" : "Wie geht es weiter",
    "When" : "Wann",
    "When Team Folders is installed and properly configured, TeamHub will automatically create a Team Folder for each new team instead of a shared personal folder. Team Folders are owned by the server, not by individual users." : "Wenn Team-Ordner installiert und richtig konfiguriert ist, erstellt TeamHub automatisch einen Team-Ordner für jedes neue Team anstelle eines geteilten persönlichen Ordners. Team-Ordner gehören dem Server, nicht einzelnen Benutzern.",
    "When IntraVox is enabled for a team, TeamHub creates a page at this path inside IntraVox. Use the format language/folder (e.g. en/teamhub or nl/teamhub). The folder must already exist in IntraVox." : "Wenn IntraVox für ein Team aktiviert ist, erstellt TeamHub eine Seite an diesem Pfad in IntraVox. Verwenden Sie das Format Sprache/Ordner (z. B. en/teamhub oder de/teamhub). Der Ordner muss bereits in IntraVox vorhanden sein.",
    "When Public is on, this message can be seen outside the team on any authenticated user’s personal feed." : "Wenn Öffentlich aktiv ist, ist diese Nachricht außerhalb des Teams für jeden angemeldeten Nutzer im persönlichen Feed sichtbar.",
    "When enabled, deleting a team produces an archive ZIP first, then applies the deletion mode below. When disabled, teams are deleted directly without producing an archive." : "Wenn aktiviert, wird beim Löschen eines Teams zuerst ein ZIP-Archiv erstellt und anschließend der unten gewählte Löschmodus angewendet. Wenn deaktiviert, werden Teams direkt ohne Archiv gelöscht.",
    "When enabled, team admins can activate Decisions for their team. Members can record and track decisions through the message stream. When disabled, all Decisions UI is hidden across the app." : "Wenn aktiviert, können Teamadministratoren Entscheidungen für ihr Team aktivieren. Mitglieder können Entscheidungen über den Nachrichtenstream aufzeichnen und verfolgen. Wenn deaktiviert, ist die gesamte Entscheidungs-Benutzeroberfläche in der App ausgeblendet.",
    "When enabled, team admins can activate a Presence tab for their team and members can set their weekly schedule. When disabled, all presence UI is hidden across the app." : "Wenn aktiviert, können Teamadministratoren einen Anwesenheits-Tab für ihr Team aktivieren und Mitglieder können ihren Wochenplan festlegen. Wenn deaktiviert, wird die gesamte Anwesenheits-Benutzeroberfläche in der App ausgeblendet.",
    "When on, members see a Public checkbox on the message composer. Public messages appear in every user’s personal feed, including users outside this team." : "Wenn aktiv, sehen Mitglieder ein Öffentlich-Kontrollkästchen im Nachrichteneditor. Öffentliche Nachrichten erscheinen im persönlichen Feed jedes Nutzers, auch außerhalb dieses Teams.",
    "When your teams post messages — or when someone publishes a public message — it will appear here." : "Wenn deine Teams Nachrichten posten – oder jemand eine öffentliche Nachricht veröffentlicht – erscheinen sie hier.",
    "Who benefits from this project, and who might be adversely affected? Who are the stakeholders?" : "Wer profitiert von diesem Projekt, und wer könnte nachteilig betroffen sein? Wer sind die Stakeholder?",
    "Who can add, edit, or delete custom links in the team tab bar." : "Wer benutzerdefinierte Links in der Team-Tab-Leiste hinzufügen, bearbeiten oder löschen darf.",
    "Who can create a team meeting." : "Wer ein Team-Meeting erstellen darf.",
    "Who can create a team meeting?" : "Wer kann eine Teambesprechung erstellen?",
    "Who can create teams" : "Wer Teams erstellen darf",
    "Who can manage custom links?" : "Wer darf benutzerdefinierte Links verwalten?",
    "Who can pin or unpin a message. One message can be pinned at a time." : "Wer eine Nachricht anpinnen oder lösen darf. Es kann jeweils nur eine Nachricht angepinnt sein.",
    "Who can post new messages, questions, and polls." : "Wer neue Beiträge, Fragen und Umfragen erstellen darf.",
    "Who can view and edit a workstream budget" : "Wer ein Arbeitsstrang-Budget sehen und bearbeiten darf",
    "Who can view and edit the Budget" : "Wer das Budget sehen und bearbeiten darf",
    "Who can view the Time tab" : "Wer kann den Zeit-Tab sehen",
    "Who sees the Budget tab" : "Wer sieht den Budget-Tab",
    "Who sees the Time tab" : "Wer sieht den Zeit-Tab",
