    "Withdrawing closes this proposal. The thread will be locked from new comments. This action cannot be undone." : "Zurückziehen schließt diesen Vorschlag. Der Thread wird für neue Kommentare gesperrt. Diese Aktion kann nicht rückgängig gemacht werden.",
    "Withdrawn" : "Zurückgezogen",
    "Without an API token the meeting wizard cannot book rooms, even when RoomVox is installed." : "Ohne API-Token kann der Besprechungsassistent keine Räume buchen, selbst wenn RoomVox installiert ist.",
