    "Workstream saved" : "Arbeitsstrang gespeichert",
    "Would you like to move the files from the shared folder into the team folder automatically, or do it manually?" : "Möchten Sie die Dateien aus dem geteilten Ordner automatisch in den Team-Ordner verschieben oder dies manuell tun?",
    "Write a comment…" : "Kommentar schreiben…",
    "Write a message (@ to mention)" : "Nachricht schreiben (@ zum Erwähnen)",
