    "You approved this decision" : "Du hast diese Entscheidung genehmigt",
    "You approved this file" : "Du hast diese Datei genehmigt",
    "You are about to remove {user} from {n} team. This cannot be undone." : ["Du bist im Begriff, {user} aus {n} Team zu entfernen. Dies kann nicht rückgängig gemacht werden.","Du bist im Begriff, {user} aus {n} Teams zu entfernen. Dies kann nicht rückgängig gemacht werden."],
    "You are about to withdraw this decision and open a new proposal in its place." : "Sie sind dabei, diese Entscheidung zurückzuziehen und einen neuen Vorschlag an ihrer Stelle zu öffnen.",
    "You are an approver and this request has been waiting %n day" : ["Du bist Genehmiger und diese Anfrage wartet seit %n Tag","Du bist Genehmiger und diese Anfrage wartet seit %n Tagen"],
    "You are an approver for this decision" : "Du bist Genehmiger für diese Entscheidung",
    "You are no longer a direct member, but you still have access to this team through a group or another team." : "Sie sind kein direktes Mitglied mehr, haben aber über eine Gruppe oder ein anderes Team weiterhin Zugriff auf dieses Team.",
    "You are not an approver for this decision." : "Du bist kein Genehmiger für diese Entscheidung.",
    "You are not currently waiting for actions from others." : "Du wartest derzeit auf keine Aktionen von anderen.",
    "You are not a member of any team." : "Du bist in keinem Team Mitglied.",
    "You can disable this message by unchecking “Getting started” under Personal settings → TeamHub." : "Sie können diese Meldung ausblenden, indem Sie „Erste Schritte“ unter Persönliche Einstellungen → TeamHub deaktivieren.",
    "You can grow to {lockAt} users before Advanced-team creation and writes lock. Upgrade the license or reduce unique team members." : "Sie können auf {lockAt} Benutzer wachsen, bevor das Erstellen erweiterter Teams und Schreibvorgänge gesperrt werden. Aktualisieren Sie die Lizenz oder reduzieren Sie die Anzahl eindeutiger Teammitglieder.",
    "You can rearrange the team’s tabs from the tab bar on its home page." : "Sie können die Reiter des Teams über die Reiterleiste auf seiner Startseite neu anordnen.",
    "You can retry below. The previous failed attempt will be cleared automatically." : "Sie können es unten erneut versuchen. Der vorherige fehlgeschlagene Versuch wird automatisch gelöscht.",
    "You denied this decision" : "Du hast diese Entscheidung abgelehnt",
    "You do not have permission to complete this card." : "Du hast keine Berechtigung, diese Karte abzuschließen.",
    "You currently have no actions requiring immediate attention." : "Du hast derzeit keine Aktionen, die sofortige Aufmerksamkeit erfordern.",
    "You completed this card" : "Du hast diese Karte abgeschlossen",
    "You do not have permission to create team meetings." : "Du hast keine Berechtigung, Teambesprechungen zu erstellen.",
    "You do not have permission to delete this comment." : "Sie haben keine Berechtigung, diesen Kommentar zu löschen.",
    "You have been designated as an approver" : "Du wurdest als Genehmiger benannt",
    "You do not have permission to perform this action on this file." : "Du hast keine Berechtigung, diese Aktion für diese Datei auszuführen.",
    "You have joined {team}" : "Sie sind {team} beigetreten",
