    "You have left {team}" : "Sie haben {team} verlassen",
    "You have unsaved changes" : "Sie haben ungespeicherte Änderungen",
    "You proposed this decision" : "Du hast diese Entscheidung vorgeschlagen",
    "You proposed this and it is waiting for an approver" : "Du hast dies vorgeschlagen und es wartet auf einen Genehmiger",
    "You proposed this and it is still open for discussion" : "Du hast dies vorgeschlagen und es steht noch zur Diskussion",
    "You requested this approval" : "Du hast diese Genehmigung angefordert",
    "You requested approval and are waiting for a response" : "Du hast eine Genehmigung angefordert und wartest auf eine Antwort",
    "You rejected this file" : "Du hast diese Datei abgelehnt",
    "You were added to this team through a group or another team. Ask your administrator to remove you." : "Sie wurden über eine Gruppe oder ein anderes Team zu diesem Team hinzugefügt. Bitten Sie Ihren Administrator, Sie zu entfernen.",
    "You were added via a group or team. Ask your administrator to remove you." : "Sie wurden über eine Gruppe oder ein Team hinzugefügt. Bitten Sie Ihren Administrator, Sie zu entfernen.",
    "You’re all caught up" : "Du bist auf dem neuesten Stand",
    "You're getting the project off the ground. Here's what to focus on:" : "Sie bringen das Projekt in Gang. Darauf sollten Sie sich konzentrieren:",
    "You're setting up your project. Here's what to focus on:" : "Sie richten Ihr Projekt ein. Darauf sollten Sie sich konzentrieren:",
    "Your approval request has been waiting %n day" : ["Deine Genehmigungsanfrage wartet seit %n Tag","Deine Genehmigungsanfrage wartet seit %n Tagen"],
    "Date to grant" : "Zu gewährendes Datum",
    "Decide the extension request for {name}" : "Über den Verlängerungsantrag für {name} entscheiden",
    "Email owner" : "Eigentümer anschreiben",
    "Extension request for {name}" : "Verlängerungsantrag für {name}",
    "Find {name} in the table below" : "{name} in der Tabelle unten suchen",
    "Loading the request…" : "Antrag wird geladen…",
    "Request extension" : "Verlängerung beantragen",
    "This request is no longer waiting for a decision. Refresh to update the list." : "Dieser Antrag wartet nicht mehr auf eine Entscheidung. Aktualisieren, um die Liste zu erneuern.",
    "Your Nextcloud administrator has configured immediate hard deletion with no archive bundle. Continuing will permanently remove the team, its files, and every TeamHub record attached to it — nothing can be restored." : "Ihre Nextcloud-Administration hat sofortiges hartes Löschen ohne Archivpaket konfiguriert. Fortfahren entfernt das Team, seine Dateien und jeden zugehörigen TeamHub-Datensatz dauerhaft — nichts kann wiederhergestellt werden.",
    "Your Nextcloud administrator has configured immediate hard deletion with no archive bundle. Continuing will permanently remove this team's collective, its page tree, and every attachment — nothing can be restored." : "Ihre Nextcloud-Administration hat sofortiges endgültiges Löschen ohne Archivpaket konfiguriert. Wenn Sie fortfahren, werden das Kollektiv dieses Teams, sein Seitenbaum und alle Anhänge dauerhaft entfernt — nichts kann wiederhergestellt werden.",
    "Your TeamHub Business license has lapsed. Renew to resume Budget, Time and Milestone updates on Advanced projects." : "Ihre TeamHub-Business-Lizenz ist abgelaufen. Erneuern Sie, um Budget-, Zeit- und Meilenstein-Updates in erweiterten Projekten fortzusetzen.",
    "Default schedule. Click a cell to change it, then click Save." : "Standardplan. Klicken Sie auf eine Zelle, um sie zu ändern, und dann auf Speichern.",
    "Email address (optional)" : "E-Mail-Adresse (optional)",
    "Your project is underway. Focus on carrying out your planned activities and tracking progress in Deck, Budget, Time and Decisions." : "Ihr Projekt läuft. Konzentrieren Sie sich auf die Umsetzung Ihrer geplanten Aktivitäten und die Fortschrittsverfolgung in Deck, Budget, Zeit und Entscheidungen.",
    "Your project is underway. Focus on carrying out your planned activities and tracking progress in Deck. Reporting tools for budget, time and progress are coming in a future update." : "Ihr Projekt läuft. Konzentrieren Sie sich auf die Durchführung der geplanten Aktivitäten und die Fortschrittsverfolgung in Deck. Auswertungstools für Budget, Zeit und Fortschritt folgen in einem zukünftigen Update.",
    "Question" : "Frage",
