    "a single project-level role. A member sees the Budget tab when their team role is at or above this level. Any member who is a named additional editor on ANY workstream also automatically sees the tab, regardless of their role." : "eine einzige Rolle auf Projektebene. Ein Mitglied sieht den Budget-Tab, wenn seine Teamrolle mindestens dieses Niveau erreicht. Jedes Mitglied, das auf IRGENDEINEM Arbeitsstrang als zusätzlicher Bearbeiter genannt ist, sieht den Tab ebenfalls automatisch, unabhängig von der Rolle.",
