    "Zero disables caching. Acting on an item always clears that member’s cache immediately, so a short lifetime is safe." : "Null deaktiviert das Zwischenspeichern. Eine Aktion an einem Eintrag leert den Cache dieses Mitglieds stets sofort, daher ist eine kurze Lebensdauer unbedenklich.",
