    "The request is waiting for approval" : "Die Anfrage wartet auf Genehmigung",
    "A moderator of {team} has been asked to approve your request. You will be able to open the team once they do." : "Ein Moderator von {team} wurde gebeten, deine Anfrage zu genehmigen. Sobald das geschehen ist, kannst du das Team öffnen.",
    "A moderator approves new members" : "Ein Moderator genehmigt neue Mitglieder",
    "Anyone may ask to join this team, but a moderator has to approve the request before you can open it." : "Jeder darf anfragen, diesem Team beizutreten, aber ein Moderator muss die Anfrage genehmigen, bevor du es öffnen kannst.",
