    "Ask for an extension if this team is still needed. Nothing is deleted when the date passes." : "Beantrage eine Verlängerung, wenn dieses Team noch gebraucht wird. Beim Überschreiten des Datums wird nichts gelöscht.",
    "About the team %s" : "Zum Team %s",
    "I am writing about the team \"%s\" on our Nextcloud." : "Ich schreibe wegen des Teams \"%s\" auf unserer Nextcloud.",
