    "Nextcloud administrators" : "Nextcloud-Administration",
    "Expiration date" : "Ablaufdatum",
    "A Nextcloud administrator set this date. Nothing is deleted when it passes — the team keeps working — but if the team is still needed, ask for more time. An administrator decides, and may grant a shorter date than the one asked for." : "Eine Nextcloud-Administration hat dieses Datum festgelegt. Wenn es verstreicht, wird nichts gelöscht – das Team funktioniert weiter –, aber wenn das Team noch gebraucht wird, können Sie um mehr Zeit bitten. Eine Administration entscheidet und kann eine kürzere Verlängerung gewähren als beantragt.",
    "Expired on {date}" : "Abgelaufen am {date}",
