    "Bulk team export requires an active TeamHub license. Add or renew a license in the License tab to unlock it." : "Der Massen-Team-Export erfordert eine aktive TeamHub-Lizenz. Fügen Sie im Tab Lizenz eine Lizenz hinzu oder erneuern Sie sie, um ihn freizuschalten.",
    "That source link cannot be opened — only http and https addresses are allowed." : "Dieser Quell-Link kann nicht geöffnet werden – nur http- und https-Adressen sind zulässig.",
