    "Minimum role to manage posts" : "Mindestrolle zum Verwalten von Beiträgen",
    "Who can pin a message, and edit or delete a message or comment written by someone else. Authors can always edit and delete their own. Every edit is shown under the post with who made it." : "Wer eine Nachricht anheften und eine Nachricht oder einen Kommentar einer anderen Person bearbeiten oder löschen kann. Autoren können ihre eigenen Beiträge immer bearbeiten und löschen. Jede Bearbeitung wird unter dem Beitrag mit dem Namen der bearbeitenden Person angezeigt.",
    "Edited by {name} on {datetime}" : "Bearbeitet von {name} am {datetime}",
    "Tags" : "Tags",
    "Classify this team with the same Nextcloud tags you use on files. An administrator manages the available tags under Settings → Administration → Basic settings." : "Klassifiziere dieses Team mit denselben Nextcloud-Tags, die du für Dateien verwendest. Ein Administrator verwaltet die verfügbaren Tags unter Einstellungen → Verwaltung → Grundeinstellungen.",
    "Remove tag {tag}" : "Tag {tag} entfernen",
    "This team has no tags yet." : "Dieses Team hat noch keine Tags.",
    "Add a tag" : "Tag hinzufügen",
    "No tags available — an administrator adds them in Basic settings" : "Keine Tags verfügbar – ein Administrator legt sie in den Grundeinstellungen an",
