    "Only the first %n page is listed" : ["Es wird nur %n Seite angezeigt","Es werden nur die ersten %n Seiten angezeigt"],
    "A group cannot own a team, so Team owner is unavailable for groups." : "Eine Gruppe kann kein Team besitzen, daher ist Teambesitzer für Gruppen nicht verfügbar.",
    "Description shown when creating a team" : "Beschreibung, die beim Erstellen eines Teams angezeigt wird",
    "Explain what this policy means for the team — who can find it, who can join, what is shared." : "Erklären Sie, was diese Richtlinie für das Team bedeutet — wer es finden kann, wer beitreten kann, was geteilt wird.",
    "Role for {name}" : "Rolle für {name}",
    "Setting member roles" : "Mitgliederrollen werden gesetzt",
    "Setting roles and handing over the team" : "Rollen werden gesetzt und das Team wird übergeben",
    "Shown under the policy dropdown in the team creation wizard, and in the list above. Leave empty to show nothing." : "Wird im Assistenten zur Teamerstellung unter der Richtlinienauswahl angezeigt, sowie in der Liste oben. Leer lassen, um nichts anzuzeigen.",
    "Team owner" : "Teambesitzer",
    "The team was created, but ownership could not be transferred. You are still the owner — you can hand over from Manage team." : "Das Team wurde erstellt, aber der Besitz konnte nicht übertragen werden. Sie sind weiterhin Besitzer — die Übergabe ist unter „Team verwalten“ möglich.",
    "You create the team and {name} becomes its owner at the end. You stay on the team as a moderator." : "Sie erstellen das Team und {name} wird am Ende Besitzer. Sie bleiben als Moderator im Team.",
    "{name} is now the owner of this team." : "{name} ist jetzt Besitzer dieses Teams.",
    "Account name" : "Kontoname",
    "Add row" : "Zeile hinzufügen",
    "Administrator" : "Administration",
