    "The OpenProject widgets disappear from this team's home for every member, and the quick actions with them." : "Die OpenProject-Widgets verschwinden für alle Mitglieder von der Team-Startseite, und mit ihnen die Schnellaktionen.",
    "Nothing changes in OpenProject: the project, its work packages and its files stay exactly as they are. You can link the project again at any time." : "In OpenProject ändert sich nichts: Das Projekt, seine Arbeitspakete und seine Dateien bleiben genau so, wie sie sind. Du kannst das Projekt jederzeit erneut verknüpfen.",
