    "OpenProject no longer accepts your connection. Reconnect your OpenProject account in your personal settings." : "OpenProject akzeptiert deine Verbindung nicht mehr. Verbinde dein OpenProject-Konto in deinen persönlichen Einstellungen erneut.",
