    "OpenProject answered in a way TeamHub does not understand. This OpenProject version may not be supported." : "OpenProject hat auf eine Weise geantwortet, die TeamHub nicht versteht. Diese OpenProject-Version wird möglicherweise nicht unterstützt.",
