    "OpenProject had a temporary problem. Try again in a moment." : "OpenProject hatte ein vorübergehendes Problem. Versuche es gleich noch einmal.",
    "OpenProject is receiving too many requests. Try again in a moment." : "OpenProject erhält zu viele Anfragen. Versuche es gleich noch einmal.",
    "This team was linked to a different OpenProject instance. Ask your Nextcloud administrator." : "Dieses Team war mit einer anderen OpenProject-Instanz verknüpft. Wende dich an deine Nextcloud-Administration.",
    "OpenProject data could not be loaded." : "OpenProject-Daten konnten nicht geladen werden.",
    "Project info" : "Projektinfo",
    "Work package" : "Arbeitspaket",
    "Show {n} more work package" : ["{n} weiteres Arbeitspaket anzeigen","{n} weitere Arbeitspakete anzeigen"],
    "Creating team and linking the OpenProject project" : "Team wird erstellt und OpenProject-Projekt verknüpft",
    "That OpenProject project is already linked to another team. Choose a different project." : "Dieses OpenProject-Projekt ist bereits mit einem anderen Team verknüpft. Wähle ein anderes Projekt.",
    "The team was not created: {error}" : "Das Team wurde nicht erstellt: {error}",
    "You can only link a project you administer in OpenProject, or a public project." : "Du kannst nur ein Projekt verknüpfen, das du in OpenProject verwaltest, oder ein öffentliches Projekt.",
    "Already linked to another team" : "Bereits mit einem anderen Team verknüpft",
    "Already linked to {team}" : "Bereits mit {team} verknüpft",
    "Failed to unlink the OpenProject project" : "Das OpenProject-Projekt konnte nicht getrennt werden",
    "Failed to unlink the OpenProject project: {error}" : "Das OpenProject-Projekt konnte nicht getrennt werden: {error}",
    "Linked against {host}, which is no longer the configured OpenProject instance." : "Verknüpft mit {host}, das nicht mehr die konfigurierte OpenProject-Instanz ist.",
    "OpenProject project unlinked from {name}" : "OpenProject-Projekt von {name} getrennt",
    "OpenProject:" : "OpenProject:",
    "Other instance" : "Andere Instanz",
    "The team keeps everything else and loses its OpenProject widgets. Nothing changes in OpenProject, and the project can then be linked by a new team. A team cannot be linked again afterwards." : "Das Team behält alles andere und verliert seine OpenProject-Widgets. In OpenProject ändert sich nichts, und das Projekt kann danach von einem neuen Team verknüpft werden. Ein Team kann nachträglich nicht erneut verknüpft werden.",
    "Unlink" : "Trennen",
    "Unlink \"{project}\" from \"{name}\"?" : "„{project}“ von „{name}“ trennen?",
