    "Due in {n} day" : ["Fällig in {n} Tag","Fällig in {n} Tagen"],
    "{shown} of {n} work package" : ["{shown} von {n} Arbeitspaket","{shown} von {n} Arbeitspaketen"],
    "Showing the first {n} match. Narrow the search to find others." : ["Nur der erste Treffer wird angezeigt. Grenze die Suche ein, um weitere zu finden.","Nur die ersten {n} Treffer werden angezeigt. Grenze die Suche ein, um weitere zu finden."],
    "One other team is already linked to this OpenProject project. Both teams will show the same project; nothing is shared between the teams themselves." : ["Ein anderes Team ist bereits mit diesem OpenProject-Projekt verknüpft. Beide Teams zeigen dasselbe Projekt; zwischen den Teams selbst wird nichts geteilt.","{n} andere Teams sind bereits mit diesem OpenProject-Projekt verknüpft. Alle zeigen dasselbe Projekt; zwischen den Teams selbst wird nichts geteilt."],
    "A project managed in OpenProject" : "Ein Projekt, das in OpenProject verwaltet wird",
    "Choose the OpenProject project for this team." : "Wähle das OpenProject-Projekt für dieses Team.",
    "Every member of this team gets the project overview and their own work packages on the team home. The project must already exist in OpenProject." : "Jedes Mitglied dieses Teams erhält die Projektübersicht und seine eigenen Arbeitspakete auf der Team-Startseite. Das Projekt muss in OpenProject bereits existieren.",
    "Linking OpenProject project" : "OpenProject-Projekt wird verknüpft",
    "OpenProject: {name}" : "OpenProject: {name}",
    "That OpenProject project is already linked to another team." : "Dieses OpenProject-Projekt ist bereits mit einem anderen Team verknüpft.",
    "The team was created, but its OpenProject project could not be linked: {error}" : "Das Team wurde erstellt, aber sein OpenProject-Projekt konnte nicht verknüpft werden: {error}",
    "Created from the OpenProject project template." : "Aus der Vorlage „OpenProject-Projekt“ erstellt.",
    "Only projects you administer in OpenProject, or public projects, are listed. A project can be linked to one team." : "Nur Projekte, die du in OpenProject verwaltest, oder öffentliche Projekte werden aufgeführt. Ein Projekt kann mit einem Team verknüpft werden.",
    "You administer this project" : "Du verwaltest dieses Projekt",
    "The OpenProject project this team was created for. It was chosen when the team was created and cannot be changed here; the project itself is managed in OpenProject." : "Das OpenProject-Projekt, für das dieses Team erstellt wurde. Es wurde beim Erstellen des Teams gewählt und kann hier nicht geändert werden; das Projekt selbst wird in OpenProject verwaltet.",
    "Edit blueprint" : "Blaupause bearbeiten",
    "Blueprint for {template}" : "Blaupause für {template}",
    "The blueprint decides what a workspace of this kind is made of on the Nextcloud side: required and optional applications, the dashboard, whether an OpenProject project is needed and which OpenProject templates may seed one, and how TeamHub roles map to OpenProject roles. What is inside the OpenProject project — work-package types, milestones, phases — is the OpenProject template's." : "Die Blaupause legt fest, woraus ein Arbeitsbereich dieser Art auf Nextcloud-Seite besteht: erforderliche und optionale Apps, das Dashboard, ob ein OpenProject-Projekt benötigt wird und welche OpenProject-Vorlagen eines erzeugen dürfen, und wie TeamHub-Rollen auf OpenProject-Rollen abgebildet werden. Was im OpenProject-Projekt steckt — Arbeitspakettypen, Meilensteine, Phasen — gehört zur OpenProject-Vorlage.",
    "This template has no stored blueprint yet; what is shown is derived from its apps and modules. Saving stores it." : "Diese Vorlage hat noch keine gespeicherte Blaupause; das Gezeigte ist aus ihren Apps und Modulen abgeleitet. Speichern legt sie an.",
    "Applications" : "Apps",
    "Application" : "App",
    "{component} required" : "{component} erforderlich",
    "{component} optional" : "{component} optional",
    "Module" : "Modul",
    "Team folder, and link the OpenProject project folder" : "Teamordner, und den OpenProject-Projektordner verknüpfen",
    "Team folder only" : "Nur Teamordner",
    "Link the OpenProject project folder only" : "Nur den OpenProject-Projektordner verknüpfen",
    "No folder" : "Kein Ordner",
    "Talk conversation" : "Talk-Unterhaltung",
    "Collectives knowledge space" : "Collectives-Wissensraum",
    "Dashboard widgets shown" : "Angezeigte Dashboard-Widgets",
    "Widgets for applications the workspace does not have are hidden anyway. Leave every box unticked to hide nothing else." : "Widgets für Apps, die der Arbeitsbereich nicht hat, werden ohnehin ausgeblendet. Lassen Sie alle Kästchen leer, um sonst nichts auszublenden.",
    "May create a new project" : "Darf ein neues Projekt anlegen",
    "May connect an existing project" : "Darf ein bestehendes Projekt verbinden",
    "May choose a parent project" : "Darf ein übergeordnetes Projekt wählen",
    "Approved OpenProject templates" : "Freigegebene OpenProject-Vorlagen",
    "Only these templates are offered when a new project is created. None ticked means every template the creator may copy." : "Nur diese Vorlagen werden beim Anlegen eines neuen Projekts angeboten. Keine Auswahl bedeutet: jede Vorlage, die der Ersteller kopieren darf.",
    "No OpenProject template is available to your account." : "Für Ihr Konto ist keine OpenProject-Vorlage verfügbar.",
    "Approved template #{id} ({name}) is not visible to your account; it stays approved." : "Freigegebene Vorlage #{id} ({name}) ist für Ihr Konto nicht sichtbar; sie bleibt freigegeben.",
    "Role mapping" : "Rollenzuordnung",
    "The OpenProject role each TeamHub role gets when a workspace is created. Memberships are created as the person creating the workspace, so OpenProject applies its own rules on top." : "Die OpenProject-Rolle, die jede TeamHub-Rolle beim Anlegen eines Arbeitsbereichs erhält. Mitgliedschaften werden im Namen der erstellenden Person angelegt, OpenProject wendet darüber hinaus seine eigenen Regeln an.",
    "TeamHub role" : "TeamHub-Rolle",
