    "Boards" : "Boards",
    "Overview page" : "Übersichtsseite",
    "Project phases" : "Projektphasen",
    "File storages" : "Dateispeicher",
    "Blueprint saved." : "Blaupause gespeichert.",
    "Blueprint reset." : "Blaupause zurückgesetzt.",
    "Project category" : "Projektkategorie",
    "e.g. Software, Construction, Governance" : "z. B. Software, Bau, Governance",
    "Visibility in OpenProject" : "Sichtbarkeit in OpenProject",
    "Who may see the team in TeamHub is the policy's setting; this is the OpenProject project's own visibility, applied when a new project is created." : "Wer das Team in TeamHub sehen darf, regelt die Richtlinie; dies ist die eigene Sichtbarkeit des OpenProject-Projekts, angewendet beim Anlegen eines neuen Projekts.",
    "Asking OpenProject what is available to you" : "OpenProject wird gefragt, was für Sie verfügbar ist",
    "Open the workspace anyway" : "Arbeitsbereich trotzdem öffnen",
    "Back to the review" : "Zurück zur Überprüfung",
    "The workspace is usable, but part of the setup needs attention. The team page shows what, and lets you retry." : "Der Arbeitsbereich ist nutzbar, aber ein Teil der Einrichtung braucht Aufmerksamkeit. Die Teamseite zeigt, was, und lässt Sie es erneut versuchen.",
    "Members and roles" : "Mitglieder und Rollen",
    "Private" : "Privat",
    "Only project members see it in OpenProject" : "Nur Projektmitglieder sehen es in OpenProject",
