    "The project identifier is already taken in OpenProject." : "Die Projektkennung ist in OpenProject bereits vergeben.",
    "OpenProject project folder" : "OpenProject-Projektordner",
    "OpenProject is not available right now." : "OpenProject ist gerade nicht verfügbar.",
    "Choose whether to create a new project or connect an existing one." : "Wählen Sie, ob ein neues Projekt angelegt oder ein bestehendes verbunden wird.",
    "Enter a valid project identifier." : "Geben Sie eine gültige Projektkennung ein.",
    "A required application is not installed. Ask an administrator." : "Eine erforderliche App ist nicht installiert. Fragen Sie eine Administration.",
    "Decide what to do with the members who have no OpenProject account." : "Entscheiden Sie, was mit den Mitgliedern ohne OpenProject-Konto geschieht.",
    "The workspace could not be started: {error}" : "Der Arbeitsbereich konnte nicht gestartet werden: {error}",
    "These parts may already hold content: {parts}. Remove the team and everything created for it? The OpenProject project is never deleted by TeamHub." : "Diese Teile enthalten möglicherweise schon Inhalte: {parts}. Das Team und alles dafür Erstellte entfernen? Das OpenProject-Projekt wird von TeamHub nie gelöscht.",
