    "Project identifier" : "Projektkennung",
    "Lowercase letters, digits, dashes and underscores. It becomes part of the project address in OpenProject and cannot be changed later." : "Kleinbuchstaben, Ziffern, Binde- und Unterstriche. Sie wird Teil der Projektadresse in OpenProject und kann später nicht geändert werden.",
    "OpenProject template" : "OpenProject-Vorlage",
    "Only templates approved for this kind of team are listed. Work packages, milestones and phases come from the template." : "Nur für diese Teamart freigegebene Vorlagen werden aufgeführt. Arbeitspakete, Meilensteine und Phasen kommen aus der Vorlage.",
    "The templates you may copy in OpenProject. Work packages, milestones and phases come from the template." : "Die Vorlagen, die Sie in OpenProject kopieren dürfen. Arbeitspakete, Meilensteine und Phasen kommen aus der Vorlage.",
    "No OpenProject template is available to you. The project will be created empty." : "Für Sie ist keine OpenProject-Vorlage verfügbar. Das Projekt wird leer angelegt.",
    "No template" : "Keine Vorlage",
    "An empty project with the default types" : "Ein leeres Projekt mit den Standardtypen",
    "Parent project" : "Übergeordnetes Projekt",
    "Search projects you may create under" : "Projekte suchen, unter denen Sie anlegen dürfen",
    "Under {name}" : "Unter {name}",
    "Parent projects" : "Übergeordnete Projekte",
    "The workspace is built around a project that already exists in OpenProject. Its members and work stay as they are." : "Der Arbeitsbereich wird um ein bereits in OpenProject bestehendes Projekt herum aufgebaut. Seine Mitglieder und seine Arbeit bleiben, wie sie sind.",
    "This kind of team connects to an existing project." : "Diese Teamart verbindet sich mit einem bestehenden Projekt.",
