    "{n} member has no OpenProject account. Decide what to do with them before continuing." : ["{n} Mitglied hat kein OpenProject-Konto. Entscheiden Sie, was damit geschieht, bevor Sie fortfahren.","{n} Mitglieder haben kein OpenProject-Konto. Entscheiden Sie, was mit ihnen geschieht, bevor Sie fortfahren."],
    "Roles in OpenProject" : "Rollen in OpenProject",
    "Each TeamHub role maps to an OpenProject role, as configured by your administrator. Memberships are created as you, so OpenProject applies its own permission rules." : "Jede TeamHub-Rolle entspricht einer OpenProject-Rolle, wie von Ihrem Administrator eingestellt. Mitgliedschaften werden in Ihrem Namen angelegt, OpenProject wendet also seine eigenen Berechtigungsregeln an.",
    "Can use" : "Kann nutzen",
    "not found in OpenProject" : "in OpenProject nicht gefunden",
