    "Another session is working on this; waiting for it." : "Eine andere Sitzung arbeitet daran; es wird gewartet.",
    "No progress for a while. It resumes on its own within a few minutes, or you can continue it now." : "Seit einer Weile kein Fortschritt. Es geht innerhalb weniger Minuten von selbst weiter, oder Sie setzen es jetzt fort.",
