    "Show the queue of this service team" : "Warteschlange dieses Serviceteams anzeigen",
    "Source group" : "Quellgruppe",
    "The people who work the queue. The owner does not need to be listed." : "Die Personen, die die Warteschlange bearbeiten. Der Verantwortliche muss nicht aufgeführt werden.",
    "The team that will answer requests" : "Das Team, das Anfragen beantworten wird",
