    "Unclaimed" : "Nicht übernommen",
    "Until this is on, the desk is being configured: nobody can request anything from it and its queue is not shown." : "Solange das aus ist, wird der Desk eingerichtet: Niemand kann etwas anfragen und die Warteschlange wird nicht angezeigt.",
    "What do you need?" : "Was brauchst du?",
    "What happens to a new request" : "Was mit einer neuen Anfrage geschieht",
